from dataclasses import dataclass

@dataclass(frozen=True)
class Point:
    x: int
    y: int

def add_points(a: Point, b: Point) -> Point:
    return Point(a.x + b.x, a.y + b.y)

def manhattan_span(a: Point, b: Point) -> int:
    return abs(a.x - b.x) + abs(a.y - b.y)

def slugify_heading(title: str) -> str:
    parts = []
    prev_dash = True
    for ch in title.strip().lower():
        if ch.isalnum():
            parts.append(ch)
            prev_dash = False
        elif not prev_dash:
            parts.append('-')
            prev_dash = True
    return ''.join(parts).strip('-')

def paginate_window(total_items: int, page_num: int, page_size: int) -> dict:
    safe_size = max(1, min(page_size, 100))
    safe_page = max(1, page_num)
    offset = (safe_page - 1) * safe_size
    total_pages = (max(0, total_items) + safe_size - 1) // safe_size
    return {'page': safe_page, 'size': safe_size, 'offset': offset, 'pages': total_pages}

def summarize_samples(samples: list) -> dict:
    if not samples:
        return {'count': 0, 'min': 0, 'max': 0, 'median': 0}
    ordered = sorted(samples)
    mid = len(ordered) // 2
    median = ordered[mid] if len(ordered) % 2 == 1 else (ordered[mid - 1] + ordered[mid]) // 2
    return {'count': len(ordered), 'min': ordered[0], 'max': ordered[-1], 'median': median}

def count_labels(labels: list) -> dict:
    tally = {}
    for raw in labels:
        cleaned = raw.strip().lower()
        if cleaned:
            tally[cleaned] = tally.get(cleaned, 0) + 1
    return tally

def normalize_headers(headers: list) -> list:
    cleaned = []
    for idx, heading in enumerate(headers):
        token = '_'.join(heading.strip().lower().split())
        cleaned.append(token if token else f'col_{idx}')
    return cleaned

export interface CalendarParts {
  readonly year: number;
  readonly month: number;
  readonly day: number;
}

export function formatCalendarLabel(parts: CalendarParts): string {
  const mm = String(parts.month).padStart(2, '0');
  const dd = String(parts.day).padStart(2, '0');
  return `${parts.year}-${mm}-${dd}`;
}

export interface ActionButtonProps {
  readonly caption: string;
  readonly disabled?: boolean;
  readonly onPress: () => void;
}

export function ActionButton({ caption, disabled = false, onPress }: ActionButtonProps) {
  return (
    <button type="button" disabled={disabled} onClick={onPress}>
      {caption}
    </button>
  );
}

export function chunkSequence(elements, chunkSize) {
  const step = Math.max(1, Math.trunc(chunkSize));
  const groups = [];
  for (let idx = 0; idx < elements.length; idx += step) {
    groups.push(elements.slice(idx, idx + step));
  }
  return groups;
}

export interface Crumb {
  readonly caption: string;
  readonly depth: number;
}

export function buildCrumbs(segments: readonly string[]): Crumb[] {
  return segments
    .map((seg) => seg.trim())
    .filter((seg) => seg.length > 0)
    .map((caption, depth) => ({ caption, depth }));
}

