pragma solidity ^0.8.24;

contract BadgeDirectory {
    struct BadgeInfo {
        string label;
        uint32 tier;
    }

    mapping(uint256 => BadgeInfo) private _badges;

    function getBadge(uint256 badgeId) external view returns (string memory, uint32) {
        BadgeInfo storage info = _badges[badgeId];
        return (info.label, info.tier);
    }
}
